"""Source05 photo/number/name/note layout and aligned optional-part layouts."""
def measured_card(root):
 def r(t,b):return ','.join(root+x for x in t.split(','))+'{'+b+'}\n'
 s=r('>.parts','display:flex;flex-direction:column;align-items:center;justify-content:center;width:100%;height:100%;min-width:0;min-height:0;text-align:center;font-size:var(--type-20);padding:3.2cqw 3.57cqw 8.93cqw;gap:var(--gap-sm);')
 s+=r('>.parts>.mark','width:23px;height:23px;flex:none;display:grid;place-items:center;border-radius:50%;background:var(--page);color:var(--ink);font-size:var(--type-18);font-weight:var(--body-weight);line-height:var(--label-line);')
 s+=r('>.parts>.mark:has(>.icon)','width:min(22cqh,96px);height:min(22cqh,96px);')+r('>.parts>.mark>.icon','width:56%;height:56%;display:grid;place-items:center;')
 s+=r('>.parts>.mark:has(>.seat)','flex:0 1 56.38cqh;width:100%;height:auto;min-height:0;border-radius:0;background:none;')+r('>.parts>.mark>.seat','height:100%;max-width:100%;width:auto;aspect-ratio:1.23;border-radius:var(--radius-sm);background:var(--n-3);color:var(--n-8);')
 s+=r('>.parts>.kick','display:grid;place-items:center;width:23px;height:23px;min-height:23px;flex:none;border-radius:50%;background:var(--page);color:var(--ink);font-size:clamp(var(--type-16),6.07cqw,var(--type-18));font-weight:var(--body-weight);line-height:var(--label-line);margin:0;')
 s+=r('>.parts>.name','font-size:clamp(var(--type-14),6.4cqw,var(--type-20));font-weight:var(--name-weight);line-height:var(--name-line);letter-spacing:var(--afterglow-card-track);margin:0;')+r('>.parts>.note','font-size:clamp(var(--type-12),5cqw,var(--type-16));font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--afterglow-card-note-track);margin:0;')+r('>.parts>.fig','font-size:clamp(var(--type-28),14cqw,var(--type-72));font-weight:var(--figure-weight);line-height:var(--figure-line);margin:0;')
 s+=r('>.parts:not(:has(>.mark))','display:grid;grid-template-rows:minmax(0,1fr) auto auto 2.5em 3.6em minmax(0,1fr);align-items:start;justify-items:center;')+r('>.parts:not(:has(>.mark))>.kick','grid-row:2;width:auto;aspect-ratio:auto;background:none;color:inherit;')+r('>.parts:not(:has(>.mark))>.fig','grid-row:3;')+r('>.parts:not(:has(>.mark))>.name','grid-row:4;')+r('>.parts:not(:has(>.mark))>.note','grid-row:5;')
 s+=r('>.parts:has(>.mark):not(:has(>.mark>.seat))','display:grid;grid-template-rows:minmax(0,1fr) auto 2.5em 3.6em minmax(0,1fr);align-items:start;justify-items:center;')+r('>.parts:has(>.mark):not(:has(>.mark>.seat))>.mark','grid-row:2;')+r('>.parts:has(>.mark):not(:has(>.mark>.seat))>.name','grid-row:3;')+r('>.parts:has(>.mark):not(:has(>.mark>.seat))>.note','grid-row:4;')
 s+=r('>.parts:has(>.mark>.seat)','justify-content:flex-start;gap:0;')+r('>.parts:has(>.mark>.seat)>.kick','margin-top:7.14cqw;margin-bottom:3.93cqw;')+r('>.parts:has(>.mark>.seat)>.name','margin-bottom:5cqw;')
 s+=r('.quiet','background:none;border-color:var(--n-3);color:var(--ink);')
 return s
